 const unsubscribeArchive=service.subscribeArchive?.(()=>{if(alive&&page==='atlas'&&!busy)void run(atlasPage);});
 const pages=[['settings','设置与绑定',setup],['atlas','图鉴 · 最新存档',atlasPage],['forms','当前表单',forms],['foundation','档案提炼',foundation],['states','状态与等级',states],['conditions','条件运行',conditions],['history','初始化与历史',history],['identity','用户身份',identity],['genesis','创世与模板',genesis],['preferences','偏好确认',preferences],['style','禁词与文风',style],['progression','世界推进',progression],['parallel','平行存档',parallel],['core','基点与原点',coreAssets],['timeline','修改时间线',timeline],['preview','预设与表单全文',preview],['assistant','缇斯亚助手',assistant]];for(const [id,name]of pages){const option=el('option',name);option.value=id;pageSelect.append(option);}pageSelect.value=page;pageSelect.onchange=()=>{const next=pageSelect.value;pageSelect.value=page;if(onAssistant&&['assistant','genesis','foundation','core','style'].includes(next)){if(busy||dirty||draft){notice.textContent='请先保存或放弃当前修改，再进入助手';return;}onAssistant(next==='core'?'core-assets':next);return;}return run(async()=>{await pages.find(p=>p[0]===next)[2]();});};
 button(root,'放弃当前未保存修改',async()=>{releaseArchiveReview(draft);if(draft?.kind==='state'){service.discardStateForm(draft.id);statePreviewIds.delete(draft.id);}draft=null;dirty=false;await pages.find(p=>p[0]===page)[2]();notice.textContent='未保存修改已放弃';});const ready=run(async()=>{await setup();if(initialPage&&initialPage!=='settings'){const target=pages.find(p=>p[0]===initialPage);check(target,'未知功能页');await target[2]();}});return {root,ready,navigate:id=>run(async()=>{const target=pages.find(p=>p[0]===id);check(target,'未知功能页');await target[2]();}),kind:'tables',keepAlive:true,settled:()=>pending,resume:()=>{if(busy)return pending;if(dirty||draft){notice.textContent='草稿已保留，保存时将核对存档版本';return Promise.resolve();}return run(pages.find(p=>p[0]===page)[2]);},requestLeave:({preserve=false}={})=>{const hasDraft=!!(dirty||draft||pageDrafts.size);return {allowed:preserve||(!busy&&!hasDraft),reason:busy&&!preserve?'表单任务正在处理，请等待或停止任务':hasDraft&&!preserve?'表单草稿尚未保存；可保留草稿后切换':'',dirty:hasDraft};},dispose(){alive=false;unsubscribeArchive?.();if(ownsArchivePreview)service.clear({scope:'archive-review',reason:'归档草案页面已关闭'});for(const id of archiveReviewIds)service.discardArchiveReview?.(id);archiveReviewIds.clear();for(const id of statePreviewIds)service.discardStateForm(id);statePreviewIds.clear();for(const id of foundationPreviewIds)service.discardFoundationPreview(id);foundationPreviewIds.clear();for(const id of conditionPreviewIds)service.discardConditionPreview(id);conditionPreviewIds.clear();pageDrafts.clear();root.remove();}};
